import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import java.util.Random;

/**
 * Represent a rectangular grid of field positions.
 * Each position is able to store a single living being.
 *
 * @version 2016.02.29
 */
public class Field
{
    // A random number generator for providing random locations.
    private static final Random rand = Randomizer.getRandom();

    private final int depth;
    private final int width;
    // Storage for living beings.
    private final LivingBeing[][] occupants;

    /**
     * Represent a field of the given dimensions.
     * @param depth The depth of the field.
     * @param width The width of the field.
     */
    public Field(int depth, int width)
    {
        this.depth = depth;
        this.width = width;
        occupants = new LivingBeing[depth][width];
    }

    /**
     * Empty the field.
     */
    public void clear()
    {
        for(int row = 0; row < depth; row++) {
            for(int col = 0; col < width; col++) {
                occupants[row][col] = null;
            }
        }
    }

    /**
     * Clear the given location.
     * @param location The location to clear.
     */
    public void clear(Location location)
    {
        occupants[location.getRow()][location.getCol()] = null;
    }

    /**
     * Place a living being at the given location.
     * If there is already a living being at the location it will
     * be lost.
     * @param being The living being to be placed.
     * @param location Where to place the living being.
     */
    public void place(LivingBeing being, Location location)
    {
        occupants[location.getRow()][location.getCol()] = being;
    }

    /**
     * Return the living being at the given location, if any.
     * @param location Where in the field.
     * @return The living being at the given location, or null if there is none.
     */
    public LivingBeing getLivingBeingAt(Location location)
    {
        return getLivingBeingAt(location.getRow(), location.getCol());
    }

    /**
     * Return the living being at the given location, if any.
     * @param row The desired row.
     * @param col The desired column.
     * @return The living being at the given location, or null if there is none.
     */
    public LivingBeing getLivingBeingAt(int row, int col)
    {
        return occupants[row][col];
    }

    /**
     * Check whether the given location is empty.
     * @param location The location to check.
     * @return true if the location has no living being.
     */
    public boolean isEmpty(Location location)
    {
        return getLivingBeingAt(location) == null;
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     * @param location Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentLocations(Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = getAdjacentLocations(location);
        for(Location next : adjacent) {
            if(isEmpty(next)) {
                free.add(next);
            }
        }
        return free;
    }

    /**
     * Try to find a free location that is adjacent to the
     * given location. If there is none, return null.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location getFreeAdjacentLocation(Location location)
    {
        // The available free ones.
        List<Location> free = getFreeAdjacentLocations(location);
        if(free.size() > 0) {
            return free.get(0);
        }
        else {
            return null;
        }
    }

    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will not include the location itself.
     * All locations will lie within the grid.
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */
    public List<Location> getAdjacentLocations(Location location)
    {
        assert location != null : "Null location passed to getAdjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -1; roffset <= 1; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -1; coffset <= 1; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * Return the depth of the field.
     * @return The depth of the field.
     */
    public int getDepth()
    {
        return depth;
    }

    /**
     * Return the width of the field.
     * @return The width of the field.
     */
    public int getWidth()
    {
        return width;
    }
}

import java.util.Random;
import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;
import java.awt.Color;

/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing bears, badgers, wolves, frogs and hedgehogs.
 *
 * @version 2022.02.24 (2)
 */
public class Simulator
{
    // Constants representing configuration information for the simulation.
    // The default width for the grid.

    private static final int DEFAULT_WIDTH = 150;
    // The default depth of the grid.
    private static final int DEFAULT_DEPTH = 100;
    // The number of simulation steps between day/night transitions.
    private static final int DAY_NIGHT_CYCLE_LENGTH = 35;

    // The probability that a hedgehog will be created in any given grid position.
    private static final double HEDGEHOG_CREATION_PROBABILITY = 0.115;
    // The probability that a bear will be created in any given grid position.
    private static final double BEAR_CREATION_PROBABILITY = 0.005;
    // The probability that a badger will be created in any given grid position.
    private static final double BADGER_CREATION_PROBABILITY = 0.1;
    // The probability that a frog will be created in any given grid position.
    private static final double FROG_CREATION_PROBABILITY = 0.125;
    // The probability that a wolf will be created in any given grid position.
    private static final double WOLF_CREATION_PROBABILITY = 0.005;
    // The probability that a plant will be created in any given grid position.
    private static final double PLANT_CREATION_PROBABILITY = 0.2;

    @FunctionalInterface
    private interface LivingBeingFactory
    {
        LivingBeing create(Field field, Location location);
    }

    private static final class SpeciesConfig
    {
        private final Class<? extends LivingBeing> type;
        private final Color color;
        private final double creationProbability;
        private final LivingBeingFactory factory;

        private SpeciesConfig(Class<? extends LivingBeing> type, Color color,
                              double creationProbability, LivingBeingFactory factory)
        {
            this.type = type;
            this.color = color;
            this.creationProbability = creationProbability;
            this.factory = factory;
        }

        private LivingBeing create(Field field, Location location)
        {
            return factory.create(field, location);
        }
    }

    private static final List<SpeciesConfig> SPECIES = List.of(
        new SpeciesConfig(Hedgehog.class, Color.YELLOW, HEDGEHOG_CREATION_PROBABILITY,
                          (field, location) -> new Hedgehog(true, field, location)),
        new SpeciesConfig(Bear.class, Color.RED, BEAR_CREATION_PROBABILITY,
                          (field, location) -> new Bear(true, field, location)),
        new SpeciesConfig(Badger.class, Color.CYAN, BADGER_CREATION_PROBABILITY,
                          (field, location) -> new Badger(true, field, location)),
        new SpeciesConfig(Frog.class, Color.MAGENTA, FROG_CREATION_PROBABILITY,
                          (field, location) -> new Frog(true, field, location)),
        new SpeciesConfig(Wolf.class, Color.PINK, WOLF_CREATION_PROBABILITY,
                          (field, location) -> new Wolf(true, field, location)),
        new SpeciesConfig(Plant.class, Color.GREEN, PLANT_CREATION_PROBABILITY,
                          (field, location) -> new Plant(true, field, location))
    );

    // List of living beings in the field.
    private final List<LivingBeing> livingBeings;
    // The current state of the field.
    private final Field field;
    // The current step of the simulation.
    private int step;

    private boolean night;
    // A graphical view of the simulation.
    private final SimulatorView view;

    public static void main(String[] args) {
        Simulator sim = new Simulator();
        sim.runMediumSimulation();
    }

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        if(width <= 0 || depth <= 0) {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        livingBeings = new ArrayList<>();
        field = new Field(depth, width);

        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width);
        configureViewColors();

        // Setup a valid starting point.
        resetSimulation();
    }

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (4000 steps).
     */
    public void runLongSimulation()
    {
        simulate(4000);
    }

    /**
     * Run the simulation from its current state for a medium period, 1000 steps
     */
    public void runMediumSimulation() {
        simulate(1000);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {

        for(int step = 1; step <= numSteps && FieldStats.isViable(field); step++) {
            simulateOneStep();
        }
    }

    /**
     * Returns if it is night time or not
     */
    public boolean isNightTime() {
        return night;
    }

    /**
     * Switches between night time and day time
     */
    private void switchNight() {
        setNight(!night);
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each
     * living being
     */
    public void simulateOneStep()
    {
        step++;
        if(step % DAY_NIGHT_CYCLE_LENGTH == 0) {
            switchNight();
        }

        // Provide space for newborn living beings.
        List<LivingBeing> newBeings = new ArrayList<>();
        // Let all living beings act.
        for(Iterator<LivingBeing> it = livingBeings.iterator(); it.hasNext(); ) {

            LivingBeing being = it.next();
            being.act(newBeings);

            if(! being.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born living beings to the main list.
        livingBeings.addAll(newBeings);

        view.showStatus(step, field);
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        resetSimulation();
    }

    private void resetSimulation()
    {
        step = 0;
        setNight(false);
        livingBeings.clear();
        populate();

        // Show the starting state in the view.
        view.showStatus(step, field);
    }

    /**
     * Randomly populate the field with living beings.
     */
    private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();

        // Goes through each cell and populates based on configured probability.
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Location location = new Location(row, col);
                populate(location, rand);
            }
        }
    }

    private void populate(Location location, Random rand)
    {
        for(SpeciesConfig species : SPECIES) {
            if(rand.nextDouble() <= species.creationProbability) {
                livingBeings.add(species.create(field, location));
                return;
            }
        }
        // Else leave the location empty.
    }

    private void configureViewColors()
    {
        for(SpeciesConfig species : SPECIES) {
            view.setColor(species.type, species.color);
        }
    }

    private void setNight(boolean night)
    {
        this.night = night;
        LivingBeing.setNightTime(night);

import java.util.List;

/**
 * A class representing shared characteristics of all living beings, animals and plants
 *
 * @version 2022.02.24
 */
public abstract class LivingBeing
{
    // Whether the being is alive or not.
    private boolean alive;
    // The being's field.
    private Field field;
    // The being's position in the field.
    private Location location;
    // Shared day/night state for all living beings in the simulation.
    private static boolean night;

    /**
     * Constructor for objects of class LivingBeing
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    @SuppressWarnings("this-escape")
    public LivingBeing(Field field, Location location)
    {
        alive = true;
        this.field = field;
        setLocation(location);
    }

    /**
     * Returns if it is night time or not
     * @return true if it is night
     */
    protected boolean isNight()
    {
        return night;
    }

    /**
     * Set the shared day/night state.
     * @param night true if the simulation is currently at night.
     */
    protected static void setNightTime(boolean nightTime)
    {
        night = nightTime;
    }

    /**
     * Return the being's location.
     * @return The being's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the being at the new location in the given field.
     * @param newLocation The being's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * Return the being's field.
     * @return The being's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Check whether the being is alive or not.
     * @return true if the being is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

    /**
     * Make this being act - that is: make it do
     * whatever it wants/needs to do.
     * @param newBeings A list to receive newly born beings.
     */
    public abstract void act(List<LivingBeing> newBeings);

    /**
     * Indicate that the being is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

}
/**
 * Represent a location in a rectangular grid.
 *
 * @version 2016.02.29
 */
public final class Location
{
    // Row and column positions.
    private final int row;
    private final int col;

    /**
     * Represent a row and column.
     * @param row The row.
     * @param col The column.
     */
    public Location(int row, int col)
    {
        this.row = row;
        this.col = col;
    }

    /**
     * Implement content equality.
     */
    @Override
    public boolean equals(Object obj)
    {
        if(!(obj instanceof Location other)) {
            return false;
        }
        return row == other.getRow() && col == other.getCol();
    }

    /**
     * Return a string of the form row,column
     * @return A string representation of the location.
     */
    @Override
    public String toString()
    {
        return row + "," + col;
    }

    /**
     * Use the top 16 bits for the row value and the bottom for
     * the column. Except for very big grids, this should give a
     * unique hash code for each (row, col) pair.
     * @return A hashcode for the location.
     */
    @Override
    public int hashCode()
    {
        return (row << 16) + col;
    }

    /**
     * @return The row.
     */
    public int getRow()
    {
        return row;
    }

    /**
     * @return The column.
     */
    public int getCol()
    {
        return col;
    }
}

